// High School course unit (docs/design/COURSES.md, brought to docs/design/COURSE_QUALITY.md's bar on 10 Oct): AP Human Geography, Unit 1, Thinking Geographically (the course's
// public outline; our own wording and questions, nothing copied). A map scale of 1 : n means one unit on the map is n of
// the same units on the ground, so map centimeters × n ÷ 100,000 gives kilometers; a large-scale map (small n) shows a
// small area in detail. Map types: choropleth (areas shaded by a rate), dot density (each dot a count), graduated
// symbol (symbols sized by amount), isoline (lines of equal value), cartogram (areas resized by data) and flow (arrows
// of movement). Projections: Mercator keeps the shapes of small areas and compass directions but swells land near the poles; Gall-Peters keeps area
// but stretches shape; Robinson compromises; azimuthal keeps true direction from its center (the equidistant kind also keeps true distance from it). Data: GPS
// finds exact positions from satellites, GIS layers data on maps in a computer, remote sensing gathers images from a
// distance. Regions: formal (one shared trait), functional (organized around a node) and perceptual (in people's
// minds). Site is a place's own physical character; situation is its position relative to other places. Absolute
// location is coordinates or an address; relative location describes a place by others. Distance decay: interaction
// falls with distance; time-space compression: technology shrinks the time distance takes. The sorted cases are the
// textbook definitions, read by hand; the scale questions are worked out from the printed numbers. Also taught: how
// governments, businesses and people use geographic data (censuses, site choice, John Snow's 1854 cholera map of the
// Broad Street pump, privacy concerns), with planning numbers marked fictional; distribution as density, concentration
// (clustered or dispersed) and pattern (linear, centralized, random); environmental determinism (rejected) and
// possibilism, sustainability (meeting today's needs without harming future generations' ability to meet theirs),
// renewable and nonrenewable resources and land use; scales of analysis and how patterns change with scale; and regions
// that overlap, weaken away from a node and have contested edges.
const tab=(title,rows,cols=['Value'])=>({t:'setups',title,head:'',rows,cols});
/* Lesson figures use 640 × 280 screen positions, converted to the figure renderer's upward y axis.
   Labels stay inside the 44..596 × 56..248 drawing window; shapes reveal in order. */
const scene=(title,draw)=>{const pts={},polys=[],segs=[],circles=[],notes=[];let i=0;const point=(x,y)=>{const k='P'+i++;pts[k]=[x,280-y];return k;};
 const pen={box:(x,y,w,h,col=0)=>{const v=[[x,y],[x+w,y],[x+w,y+h],[x,y+h]].map(([a,b])=>point(a,b)).join('');polys.push({v,col});},line:(x,y,u,v,col=0,arrows=0,dash=false,w=2)=>segs.push({v:point(x,y)+point(u,v),col,arrows,dash,w}),circle:(x,y,r,col=0)=>circles.push({c:point(x,y),r,col}),note:(x,y,text,col=0)=>notes.push({at:[x,280-y],text,col})};
 draw(pen);return {t:'figure',title,view:[44,596,32,224],pts,hide:Object.keys(pts).join(''),dots:'',polys,segs,circles,notes};};
const board=(title,lines)=>({t:'board',title,lines,box:true});
const art=(title,items)=>({t:'art',title,items:items.map(([src,x,label])=>({src:'hug/'+src+'.png',x,y:222,h:140,label}))});
/* Spherical Mercator and Gall-Peters graticules, same globe scale; latitude clipped at ±70°.
   x = longitude (× cos 45° for Peters); y = ln tan(π/4 + latitude/2), or sin(latitude)/cos 45°. */
const projections=()=>scene('Flattening a globe: two graticules',d=>{const rad=v=>v*Math.PI/180;for(const [cx,kind] of [[178,0],[466,1]]){const xy=(lon,lat)=>[cx+45*rad(lon)*(kind?Math.SQRT1_2:1),151-45*(kind?Math.sin(rad(lat))/Math.SQRT1_2:Math.log(Math.tan(Math.PI/4+rad(lat)/2)))];
 for(const lat of [-60,-30,0,30,60]){const a=xy(-135,lat),b=xy(135,lat);d.line(...a,...b,kind,0,false,lat===0?3:1);}
 for(const lon of [-135,-90,-45,0,45,90,135]){const a=xy(lon,-70),b=xy(lon,70);d.line(...a,...b,kind);}
 d.note(cx,65,kind?'Gall-Peters: area':'Mercator: local shape',kind);d.note(cx,240,kind?'Shapes stretch':'Polar areas enlarge',kind);}});
const n=v=>v.toLocaleString('en-US');
const pct=v=>String(Math.round(v*1e6)/1e6);
const MAPS=[['shading each state by its unemployment rate','choropleth'],['showing each city as a circle sized by its population','graduated symbol'],['placing one dot for every 1,000 farms','dot density'],
 ['drawing lines that connect places with the same elevation','isoline'],['resizing each country by the size of its population','cartogram'],['using arrows to show how many people moved between countries','flow'],
 ['shading each county by its median household income','choropleth'],['drawing lines of equal average temperature','isoline'],['sizing a symbol at each port by the tonnage it ships','graduated symbol'],
 ['placing one dot for every 500 voters','dot density'],['enlarging each country according to its wealth','cartogram'],['showing trade between countries with arrows of different widths','flow']];
const PROJ=[['keeps the shapes of small areas and true compass directions, but makes Greenland look as big as Africa','Mercator'],['shows every area at its true relative size, but stretches the shapes of continents','Gall-Peters'],
 ['distorts area, shape, distance and direction a little each, so no one is badly wrong','Robinson'],['shows true direction from its center point, often a pole','azimuthal'],
 ['is the one sailors used, because a straight line on it is a line of constant compass bearing','Mercator'],['is an equal-area map chosen to show the true size of countries near the equator','Gall-Peters']];
const DATA=[['A delivery app finds a driver\'s exact position from satellites.','GPS'],['A city layers maps of roads, schools and flood zones in a computer to plan a new park.','GIS'],['Satellites photograph a forest each year to measure how much has been cut down.','remote sensing'],
 ['A hiker\'s phone shows her latitude and longitude.','GPS'],['Planners overlay population and bus routes to see who lives far from a stop.','GIS'],['An aircraft takes infrared images of crops to spot drought.','remote sensing'],
 ['A farmer\'s tractor steers itself along rows using satellite positions.','GPS'],['A health agency maps disease cases on top of water sources to find a pattern.','GIS'],['Weather satellites image a hurricane from space.','remote sensing']];
const REG=[['the Corn Belt, where most farms grow corn','formal'],['the area a pizza shop delivers to','functional'],['the American South, as people imagine it','perceptual'],['the countries where Spanish is the main language','formal'],
 ['the area a TV station\'s signal reaches','functional'],['the Midwest, whose edges people disagree about','perceptual'],['a country with a clear border and one government','formal'],['the zone of suburbs from which people commute to one city','functional'],
 ['"the Bible Belt," a name people use for a loosely defined area','perceptual'],['the region with a Mediterranean climate','formal'],['the area served by one hospital','functional'],['"Down Under," a nickname for Australia and New Zealand','perceptual']];
const SITE=[['The city was built on a hill above a river, with good farmland around it.','site'],['The city grew where two major trade routes crossed.','situation'],['The town has a deep natural harbor.','site'],['The port is the closest one to the country\'s capital.','situation'],
 ['The village sits on flat, fertile soil near fresh water.','site'],['The town lies halfway between two large markets.','situation'],['The city is protected by marshes on three sides.','site'],['The city is the gateway between the coast and the mountain mines inland.','situation']];
const LOC=[['40° N, 74° W','absolute'],['next to the train station, two blocks from the river','relative'],['1600 Pennsylvania Avenue NW, Washington, DC','absolute'],['a short drive south of the airport','relative'],
 ['the latitude and longitude of the Eiffel Tower','absolute'],['across the street from the school','relative']];
const CONC=[['Customers come mostly from nearby; very few travel from far away to shop there.','distance decay'],['A video call lets people on two continents talk instantly, where letters once took weeks.','time-space compression'],
 ['Fewer people visit a park the farther away they live.','distance decay'],['Jet travel turned a months-long sea voyage into a day\'s flight.','time-space compression'],['A store sells less to towns that are farther from it.','distance decay'],
 ['Online news spreads around the world within minutes.','time-space compression'],['Phone calls between two cities drop off as the cities get farther apart.','distance decay'],['A high-speed rail line puts two cities an hour apart instead of five.','time-space compression']];
/* The four Try-it questions in pool form; the generator skips them. */
const TRY=['On a map with a scale of 1 : 100,000, two towns are 5 centimeters apart. How many kilometers apart are they?',
 'A map shades each country by its birth rate. Which kind of map is it: choropleth, dot density, graduated symbol, isoline, cartogram, or flow?',
 'A newspaper\'s delivery area is centered on its printing plant. Which kind of region is it: formal, functional, or perceptual?',
 'A fictional reservoir holds 600 million liters. People take 50 million liters a year and rain adds 20 million. If nothing changes, in how many years will it be empty?'];
/* lettered choices, the right one moved to position k */
const choose=(right,wrong,k)=>{const o=[...wrong];o.splice(k%3,0,right);return {text:o.map((x,i)=>`${'ABC'[i]}: ${x}`).join(', '),letter:'ABC'[o.indexOf(right)]};};
const tryIt=s=>`Try it: ${s[0].toLowerCase()+s.slice(1)}`;
const MAPK='choropleth, dot density, graduated symbol, isoline, cartogram, or flow';
export default {
id:'geography-h-ap-hug-thinking-geographically',subject:'geography',level:5,grade:9,standard:'AP Human Geography, Unit 1',
title:'Thinking geographically',
goal:'Work with map scale, choose map types and projections, tell GPS, GIS and remote sensing apart, explain how geographic data guide decisions, describe location, place and distribution, weigh determinism, possibilism and sustainability, compare scales of analysis, and sort regions.',
points:20,
skills:{scale:'Map scale',maps:'Map types and projections',data:'Geographic data',power:'Using geographic data',concepts:'Spatial concepts',hei:'People and environment',scales:'Scales of analysis',regions:'Regions'},
outline:[['1.1','Introduction to maps',['scale','maps']],['1.2','Geographic data',['data']],['1.3','The power of geographic data',['power']],['1.4','Spatial concepts',['concepts']],['1.5','Human-environmental interaction',['hei']],['1.6','Scales of analysis',['scales']],['1.7','Regional analysis',['regions']]],
steps:[
 {skill:"scale",say:"Map scale converts a measured map distance into ground distance. In this fictional example, 3 centimeters at 1 : 80,000 represents 240,000 ground centimeters. Divide by 100,000 to convert centimeters to kilometers, giving 2.4 kilometers.",eq:"km = map cm × scale denominator ÷ 100,000",pic:board('Fictional route: map distance → ground distance',['Scale: 1 : 80,000; map distance: 3 cm','Ground cm = 3 × 80,000 = 240,000','Ground km = 240,000 ÷ 100,000','Distance = 2.4 km']),
  check:{prompt:tryIt(TRY[0]),answer:5,options:[5,50,0.5],hint:'5 × 100,000 = 500,000 cm. Divide by 100,000.',pic:tab('The map',[['scale','1 : 100,000'],['distance','5 cm']])}},
 {skill:"scale",say:"A large-scale map shows a small area in detail. These fictional maps occupy equal-sized frames: the left covers 200 meters across, the right 2 kilometers. The highlighted block becomes much smaller on the right. A smaller scale denominator means a larger map scale.",pic:scene('Equal frames, different scales',d=>{d.box(80,92,180,108);d.box(380,92,180,108);d.box(98,116,54,54,1);d.box(398,116,5.4,5.4,1);for(const x of [164,208])d.line(x,92,x,200,2);for(const y of [110,180])d.line(80,y,260,y,2);d.line(280,146,358,146,1,1);d.note(170,72,'Large scale');d.note(470,72,'Small scale');d.note(170,222,'200 m across');d.note(470,222,'2 km across');d.note(320,244,'Fictional: same block shown at 1/10 the width');})},
 {skill:"maps",say:"Choose a thematic map to match the data. A choropleth shades whole areas by a rate or value. A dot-density map gives each dot a fixed count; dots need not locate individual people. Graduated symbols represent amounts with different symbol sizes. These sketches use fictional data.",pic:scene('Fictional thematic maps',d=>{d.box(70,105,58,88,0);d.box(128,105,58,88,1);d.note(128,78,'Choropleth');d.note(128,219,'Share aged 65+');d.note(98,148,'10%');d.note(157,148,'30%');d.box(263,105,114,88,2);for(const [x,y] of [[280,124],[300,151],[330,133],[350,175]])d.circle(x,y,3,2);d.note(320,78,'Dot density');d.note(320,219,'1 dot = 200 people');d.circle(461,149,12,3);d.circle(528,149,24,3);d.note(498,78,'Graduated symbol');d.note(461,189,'100');d.note(528,189,'400');d.note(498,219,'Circle area = count');}),
  check:{prompt:tryIt(TRY[1]),answer:'choropleth',options:['choropleth','isoline','cartogram'],hint:'Areas shaded by a rate.',pic:tab('The map',[['data','birth rate'],['how','each country shaded']])}},
 {skill:"maps",say:"Other map types reveal different relationships. Isolines connect equal values such as elevation. Cartograms resize places according to data rather than land area. Flow maps use arrows to show movement; their widths can show the amount moving. Read the legend before interpreting any map.",pic:scene('More maps (fictional)',d=>{d.circle(134,147,50,0);d.circle(134,147,30,0);d.note(134,147,'200 m');d.note(134,190,'100 m');d.note(134,76,'Isoline');d.box(267,130,35,35,1);d.box(311,112,70,70,1);d.note(285,199,'1 unit');d.note(348,199,'4 units');d.note(320,76,'Cartogram');d.circle(470,118,6,2);d.circle(540,185,6,2);d.line(478,123,535,178,2,1,false,7);d.line(536,192,468,145,3,1,false,2);d.note(505,76,'Flow');d.note(320,236,'Legend: cartogram area and arrow width encode amount');})},
 {skill:"maps",say:"Every flat map distorts the round Earth. Watch the spacing between latitude lines: Mercator spreads high latitudes apart, preserving local shape but enlarging polar areas. Its straight routes have constant compass bearings. Gall-Peters preserves relative area and distorts shape. These are coordinate-grid sketches, not maps of measured population.",pic:projections()},
 {skill:"maps",say:"A projection is a choice about which properties matter. Robinson compromises among distortions for a world overview. An azimuthal map preserves directions from its center; the equidistant kind also preserves distances from that center. Neither promise applies to every possible pair of points.",pic:scene('Azimuthal: the center is special',d=>{d.circle(206,154,68,0);d.circle(206,154,34,0);for(const [x,y] of [[206,86],[274,154],[206,222],[138,154]])d.line(206,154,x,y,0,1);d.note(206,154,'Center');d.note(445,99,'True directions from center');d.note(445,142,'Equidistant kind:');d.note(445,164,'true distances from center');d.note(445,209,'Robinson: a compromise');})},
 {skill:"data",say:"Geographic tools do different jobs. A GPS receiver uses satellite signals to estimate its position. Remote sensing records Earth from aircraft or satellites. GIS combines layers such as roads, homes and flood zones. Counts are quantitative data; interviews and descriptions are qualitative data.",pic:scene('Position + images + records → GIS layers',d=>{d.box(60,88,146,38,0);d.note(133,107,'GPS: position');d.box(60,161,146,46,1);d.note(133,177,'Remote sensing');d.note(133,194,'images');d.line(215,108,325,140,0,1);d.line(215,183,325,156,1,1);d.box(350,98,174,72,2);d.box(363,114,174,72,0);d.box(376,130,174,72,3);d.note(463,153,'GIS: overlay');d.note(463,179,'roads + homes');d.note(320,236,'Fieldwork and censuses add records');})},
 {skill:"power",say:"A map can guide a decision by revealing who is served. In this fictional town, the circular walking range leaves homes outside it, suggesting a place to investigate for a new stop. Governments plan services, businesses choose sites, and individuals plan routes. Check the data date, map choices and privacy before relying on location records.",pic:scene('Fictional transit access',d=>{d.line(80,161,554,161,0,0,false,4);d.circle(208,161,64,1);d.circle(208,161,5,1);for(const [x,y] of [[160,120],[224,115],[246,193],[420,110],[464,126],[496,194]])d.box(x,y,13,13,2);d.note(208,79,'Existing stop');d.note(465,79,'Homes beyond range');d.line(448,150,448,177,3,0,true);d.note(320,238,'Investigate access before adding a stop');})},
 {skill:"concepts",say:"Describe a place in two ways. Site means its own physical features, such as a riverbank. Situation means its position relative to other places and routes. An address or coordinates give absolute location; saying a town is east of a bridge gives relative location. The sketch shows these different descriptions of one fictional town.",pic:scene('Describing a fictional town',d=>{d.line(185,84,213,130,0,0,false,10);d.line(213,130,190,214,0,0,false,10);d.line(72,161,556,161,1,0,false,3);d.box(179,152,36,18,3);d.box(286,122,58,69,2);d.line(345,155,530,100,1,1);d.note(310,101,'Town');d.note(125,77,'Riverbank: site');d.note(457,78,'Route to market');d.note(320,219,'Relative: east of bridge');d.note(320,241,'Absolute: 12 River Road (fictional)');})},
 {skill:"concepts",say:"Distance decay means interaction tends to weaken as distance increases. Time-space compression is a different idea: faster transport and communication reduce the time needed to connect places. In this fictional comparison, the places stay the same distance apart even though the journey becomes quicker.",pic:scene('Distance, contact and time',d=>{for(const [x,r] of [[110,18],[245,12],[380,7],[515,3]])d.circle(x,110,r,0);d.note(320,70,'Distance decay: fewer contacts farther away');d.line(110,151,515,151,0,1);d.note(320,173,'Increasing distance from the origin');d.line(110,210,515,210,1);d.note(320,234,'Fictional trip: 8 hours → 2 hours');})},
 {skill:"concepts",say:"Density counts objects per unit area; concentration describes how closely they are grouped. Each frame here contains six homes on the same area, so density is identical. The left is clustered, the middle dispersed, and the right forms a linear pattern. Density alone cannot describe that arrangement.",pic:scene('Fictional settlement patterns',d=>{for(const x of [65,260,455])d.box(x,99,120,107,0);for(const [x,y] of [[98,126],[111,127],[124,126],[100,141],[114,144],[127,140],[278,119],[327,115],[356,137],[288,178],[326,164],[358,191],[469,185],[487,172],[505,159],[523,146],[541,133],[559,120]])d.box(x,y,6,6,2);d.note(125,78,'Clustered');d.note(320,78,'Dispersed');d.note(515,78,'Linear pattern');d.note(320,236,'Density = 6 homes ÷ the same land area');})},
 {skill:"hei",say:"The environment creates limits and opportunities; it does not decide a society’s fate. Terraces turn a steep slope into flatter fields, while dikes can protect low land from water. These choices illustrate possibilism. Environmental determinism, the claim that nature decides social development, is rejected because it ignores human choice.",pic:[art('Possibilism: people adapt land',[['terraced-fields',170,'Mountain farming: terraces']]),{t:'figure',view:[-13,13,-1.4,6.6],pts:{A:[0.5,0],B:[4,0],C:[4,3],D:[0.5,3],E:[4,0],F:[7.5,0],G:[6.6,4],H:[4.9,4],J:[7.5,0],K:[12,0],L:[12,1],M:[7.5,1],P:[0.5,3],Q:[12,3]},hide:'ABCDEFGHJKLMPQ',dots:'',polys:[{v:'ABCD',col:0},{v:'EFGH',col:2},{v:'JKLM',col:1}],segs:[{v:'PQ',dash:true,col:0,w:1.5}],notes:[{at:[2.2,1.5],text:'sea'},{at:[5.75,2],text:'dike'},{at:[9.8,1.7],text:'polder below sea level'},{at:[10.6,3.5],text:'sea level',col:0},{at:[6.2,-0.9],text:'Netherlands: dike'}]}]},
 {skill:"hei",say:"Sustainability means meeting present needs while protecting future generations’ ability to meet theirs. Renewable does not mean unlimited: water stores can fall when withdrawals exceed replenishment. Sunlight and wind renew naturally; coal and oil form too slowly to replace what we use on a human time scale.",pic:scene('Water: inflow and outflow',d=>{d.box(241,105,157,94,0);d.note(320,147,'Reservoir');d.line(90,148,230,148,2,1,false,4);d.line(410,148,551,148,1,1,false,7);d.note(143,105,'Replenishment');d.note(490,105,'Withdrawal');d.note(320,225,'Outflow > inflow → the store falls');}),
  check:{prompt:tryIt(TRY[3]),answer:20,options:[20,12,8.6],hint:'Each year it loses what is taken minus what rain adds.',pic:tab('A fictional reservoir',[['holds','600 million liters'],['taken each year','50 million'],['added each year','20 million']])}},
 {skill:"scales",say:"Scale of analysis is the area used to study a pattern, not the ratio printed on a map. A national total can rise while one town shrinks. These fictional counts show why: growth in one part can outweigh decline elsewhere. Compare local, regional, national and global evidence before generalizing.",pic:scene('Fictional local vs national change',d=>{d.box(127,82,384,118,0);d.box(152,104,142,70,1);d.box(344,104,142,70,2);d.note(223,127,'Town A');d.note(223,153,'1,100 → 1,000');d.note(415,127,'Rest of country');d.note(415,153,'8,900 → 9,400');d.note(320,224,'National total: 10,000 → 10,400');d.note(320,245,'Local decline; national growth');})},
 {skill:"regions",say:"A formal region shares a defining trait, such as a crop or a government. A functional region links places to a central node through commuting, deliveries or services. A perceptual region reflects how people imagine an area; its edges may differ from person to person. The sketches represent these three ways of grouping places.",pic:scene('Three ways to define a region (schematic)',d=>{d.box(70,105,120,90,2);d.note(130,146,'Shared trait');d.note(130,77,'Formal');d.circle(320,149,7,0);for(const [x,y] of [[278,112],[360,112],[277,189],[362,189]]){d.circle(x,y,4,0);d.line(x,y,320,149,0,1);}d.note(320,77,'Functional');d.note(320,219,'Node + links');d.circle(502,149,48,3);d.circle(519,153,42,1);d.note(514,149,'Fuzzy edges');d.note(514,77,'Perceptual');}),
  check:{prompt:tryIt(TRY[2]),answer:'functional',options:['formal','functional','perceptual'],hint:'It is organized around one central place.',pic:tab('The region',[['center','the printing plant']])}},
 {skill:"regions",say:"Regions can overlap because each answers a different question. This fictional town belongs both to an administrative district and to a service area centered on a nearby node. Functional connections often weaken away from the node. Perceptual boundaries may be contested because people define the same named region differently.",pic:scene('One place can belong to several regions',d=>{d.box(135,90,220,126,0);d.circle(390,155,70,1);d.circle(390,155,6,1);d.circle(333,155,5,3);d.line(339,155,383,155,1);d.note(232,70,'District boundary');d.note(455,70,'Service area');d.note(289,181,'Town');d.note(432,184,'Node');d.note(320,240,'Different criteria → overlapping regions');})},
 {skill:"regions",summary:true,say:"To think geographically, start with a question and choose the evidence that can answer it. Select map scale, projection and data display for that purpose, then look for spatial patterns and human-environment relationships. Finally, test whether your conclusion changes with the scale of analysis or the boundaries of a region.",pic:scene('Unit 1: explain a spatial pattern',d=>{for(const [x,y,w,label,col] of [[60,95,140,'Question',0],[250,95,140,'Map + data',1],[440,95,140,'Pattern',2],[250,190,140,'Explanation',3]]){d.box(x,y,w,36,col);d.note(x+w/2,y+18,label,col);}d.line(202,113,247,113,0,1);d.line(393,113,437,113,1,1);d.line(510,137,395,207,2,1);d.line(244,207,127,137,3,1);d.note(170,174,'Check scale + region');})}],
progression:{requires:['geography-m-coordinates','geography-m-ratio-scale'],operations:2,demand:'Convert map distances through a ratio scale, work out densities and planning numbers, and match a map, a projection, a data source, a scale or a region to its definition.'},
items(add){
 const seen=new Set(TRY);
 const put=(skill,prompt,answer,pic,explanation,accept)=>{if(seen.has(prompt))return;seen.add(prompt);add(skill,prompt,answer,pic,explanation,accept);};
 /* scale: map to ground, ground to map, and which scale is larger */
 for(const [sc,cm] of [[50000,6],[25000,8],[200000,3],[1000000,4.5],[24000,10],[250000,2],[100000,7.5],[500000,3.2]]){const km=cm*sc/100000;
  put('scale',`On a map with a scale of 1 : ${n(sc)}, two towns are ${cm} centimeters apart. How many kilometers apart are they?`,Math.round(km*1e6)/1e6,tab('The map',[['scale',`1 : ${n(sc)}`],['distance',`${cm} cm`]]),`${cm} × ${n(sc)} = ${n(cm*sc)} cm, which is ${pct(km)} km.`);}
 for(const [sc,km] of [[200000,12],[50000,1.5],[1000000,40],[25000,2],[100000,3.5],[500000,25]]){const cm=km*100000/sc;
  put('scale',`Two places are ${km} kilometers apart. On a map with a scale of 1 : ${n(sc)}, how many centimeters apart are they?`,Math.round(cm*1e6)/1e6,tab('The map',[['scale',`1 : ${n(sc)}`],['ground distance',`${km} km`]]),`${km} km = ${n(km*100000)} cm; ÷ ${n(sc)} = ${pct(cm)} cm.`);}
 for(const [a,b] of [[24000,1000000],[50000,250000],[10000000,62500],[100000,5000],[2000000,24000],[1200,1200000]]){const big=a<b?a:b;
  put('scale',`Which map is larger scale, showing a smaller area in more detail: 1 : ${n(a)} or 1 : ${n(b)}?`,`1 : ${n(big)}`,tab('Two maps',[['first',`1 : ${n(a)}`],['second',`1 : ${n(b)}`]]),`The smaller number after the colon, ${n(big)}, means each map unit covers less ground, so 1 : ${n(big)} is the larger scale.`,[`1:${n(big)}`,`1:${big}`,`1 : ${big}`]);}
 for(const [s,v] of [['A map of one neighborhood showing every house.','large'],['A map of the whole world on one page.','small'],['A city street map.','large'],['A map of an entire continent.','small'],['A campus map showing each building.','large'],['A map of all of Asia.','small']])
  put('scale',`${s} Is it a large-scale or a small-scale map?`,v,tab('The map',[['shows',s]],['']),v==='large'?'It shows a small area in detail: large scale.':'It shows a big area with little detail: small scale.');
 /* maps: types and projections */
 for(const [d,k] of MAPS)put('maps',`A map is made by ${d}. Which kind of map is it: ${MAPK}?`,k,tab('A thematic map',[['how',d]],['']),{choropleth:'Areas shaded by a rate or value make a choropleth map.','graduated symbol':'Symbols sized by amount make a graduated symbol map.','dot density':'Each dot standing for a count makes a dot density map.',isoline:'Lines joining equal values make an isoline map.',cartogram:'Areas resized by data make a cartogram.',flow:'Arrows showing movement make a flow map.'}[k]);
 for(const [d,k] of PROJ)put('maps',`Which projection ${d}: Mercator, Gall-Peters, Robinson, or azimuthal?`,k,tab('A projection',[['clue',d]],['']),`That is the ${k} projection.`,[k.toLowerCase()]);
 for(const [s,yes] of [['Every flat map distorts the Earth in some way.','yes'],['The Mercator projection shows Greenland at its true size.','no'],['An equal-area projection keeps the sizes of countries in true proportion.','yes'],['The Robinson projection is perfectly accurate in area.','no']])
  put('maps',`True or false, answered yes or no: ${s}`,yes,tab('Projections',[['statement',s]],['']),yes==='yes'?'Yes: that is how projections behave.':'No: that projection distorts it.');
 /* data: GPS, GIS, remote sensing; and quantitative or qualitative */
 for(const [s,k] of DATA)put('data',`${s} Which is this: GPS, GIS, or remote sensing?`,k,tab('Geographic data',[['case',s]],['']),{GPS:'Satellites giving an exact position: GPS.',GIS:'Layers of data combined on a map in a computer: GIS.','remote sensing':'Images gathered from a distance: remote sensing.'}[k],[k.toLowerCase()]);
 for(const [s,k] of [['a count of people in each city','quantitative'],['interviews about how residents feel about their neighborhood','qualitative'],['average rainfall each month','quantitative'],['photos and stories collected from local people','qualitative'],
  ['the percent of land used for farming','quantitative'],['a diary describing life on a farm','qualitative'],['the number of cars crossing a bridge each hour','quantitative'],['notes from watching how people use a park','qualitative'],
  ['census data on household income','quantitative'],['open-ended survey answers about a festival','qualitative'],['the population density of each county','quantitative'],['a recorded conversation with an elder about the town\'s history','qualitative']])
  put('data',`Is ${s} quantitative or qualitative data?`,k,tab('Data',[['source',s]],['']),k==='quantitative'?'It is measured in numbers: quantitative data.':'It is descriptive, in words or images: qualitative data.');
 /* regions */
 for(const [d,k] of REG)put('regions',`Which kind of region is ${d}: formal, functional, or perceptual?`,k,tab('A region',[['region',d]],['']),k==='formal'?'It is defined by one shared trait: a formal region.':k==='functional'?'It is organized around a central node: a functional region.':'It exists in people\'s minds with fuzzy edges: a perceptual region.');
 for(const [d,k] of [['data for every country on Earth','global'],['data about one city\'s neighborhoods','local'],['data comparing the states of one country','national'],['data for the countries of South America','regional'],['data for the whole world\'s oceans','global'],['data about one town\'s streets','local'],
  ['data comparing the provinces of Canada','national'],['data for the countries of Southeast Asia','regional']])
  put('scales',`A study uses ${d}. At which scale of analysis is it: local, regional, national, or global?`,k,tab('Scale of analysis',[['data',d]],['']),`It looks at ${k==='local'?'a small place':k==='regional'?'a group of countries':k==='national'?'the parts of one country':'the whole world'}: ${k} scale.`);
 /* concepts: site and situation, absolute and relative location, distance decay and time-space compression */
 for(const [s,k] of SITE)put('concepts',`${s} Does this describe the city's site or its situation?`,k,tab('A city',[['fact',s]],['']),k==='site'?'It is about the place\'s own physical features: site.':'It is about its position relative to other places: situation.');
 for(const [s,k] of LOC)put('concepts',`Is "${s}" an absolute location or a relative location?`,k,tab('A location',[['given',s]],['']),k==='absolute'?'Coordinates or an address pin it down exactly: absolute location.':'It describes the place by other places: relative location.');
 for(const [s,k] of CONC)put('concepts',`${s} Is this distance decay or time-space compression?`,k,tab('Space',[['case',s]],['']),k==='distance decay'?'Interaction falls as distance grows: distance decay.':'Technology shrinks the time it takes to cross distance: time-space compression.');
 /* power: how governments, businesses and people use geographic data */
 [['A city maps where traffic crashes happen most and adds crosswalks at those spots. What does this show?','geographic data guiding a government decision',['a perceptual region forming','data that cannot affect policy'],'The city used mapped crash data to decide where to put crosswalks. That is a government using geographic data to make a policy decision.'],
  ['A coffee chain studies maps of income, foot traffic and rival shops before choosing where to open. Who is using geographic data here?','a business',['a census bureau','a weather service'],'The coffee chain is a business. It uses maps of income, foot traffic and rivals to pick a site where it expects the most customers.'],
  ['Why do many governments count their whole population in a census?','to plan services and share out resources and representation',['to set the prices of goods','to map the ocean floor'],'A census shows how many people live where, so governments can plan schools and hospitals, share out funds and draw election districts fairly.'],
  ['In 1854 John Snow studied a cholera outbreak in London and mapped the deaths. Around what were they clustered?','a water pump on Broad Street',['the river Thames','the city\'s hospitals'],'Snow mapped each cholera death and found them clustered around the Broad Street pump. He persuaded officials to remove its handle, linking the disease to dirty water.'],
  ['Health officials map cases of an illness and find them clustered around one water source. What is a sensible next step?','test the water source and close it if it is contaminated',['ignore the map, since maps cannot help','move the hospital farther away'],'A cluster around one water source suggests the water may be spreading the illness. Testing it, and closing it if it is contaminated, deals with the likely cause.'],
  ['Planners want to know which homes are far from any bus stop. Which tool shows this best?','GIS, layering bus stops over where people live',['a single photo of one street','a list of bus drivers\' names'],'GIS stacks map layers, such as bus stops and homes, so planners can measure which homes are far from any stop. One photo or a list cannot show that.'],
  ['A farmer uses satellite images of crop health to decide where to add fertilizer. What is this called?','precision agriculture',['subsistence farming','shifting cultivation'],'Precision agriculture uses satellite, GPS and sensor data to give each part of a field just what it needs, such as fertilizer only where crops are weak.'],
  ['Why can a map mislead even when its data are correct?','choices of scale, color and units change what it seems to show',['correct data always make only one possible map','maps involve no choices'],'Mapmakers choose the scale, colors, class breaks and units. With the same correct data, different choices can make a pattern look bigger or smaller.'],
  ['Why might a school district use census data when deciding where to build a new school?','it shows where the number of school-age children is growing',['it lists every student\'s grades','it shows the soil type under each school'],'Census data show where young children live and how numbers are changing, so a district can build where the number of school-age children is growing.'],
  ['Emergency planners map the areas that flood most often. How can they use the map?','to limit building there and plan evacuation routes',['to predict the exact day of the next flood','to stop rain from falling'],'Flood maps show where floods happen most, so planners can limit building there and plan escape routes. They cannot predict the exact day of a flood.'],
  ['What is a common worry about collecting location data from millions of phones?','it can threaten people\'s privacy',['phones cannot record location','the data are always too small to use'],'Phone location data can reveal where people live, work and go, so it can threaten privacy if it is shared or misused.'],
  ['Who uses geographic data to make decisions?','governments, businesses and individuals',['only governments','only scientists'],'Governments, businesses and ordinary people all use geographic data, for policy, for choosing sites and for daily choices like routes.'],
  ['A shopper uses a map app to find the fastest route around a traffic jam. What is this an example of?','an individual using geographic data to decide',['a government setting policy','a formal region'],'The shopper is an individual using map data to make a personal choice. No government policy or formal region is involved.'],
  ['Why should damage maps after a disaster be updated with new satellite images?','conditions change, and decisions need current data',['old images are always more accurate','satellites cannot see damage'],'After a disaster, conditions change fast: water rises or falls and roads reopen. Rescuers need current images to send help where it is needed now.']].forEach(([q,right,wrong,why],k)=>{const c=choose(right,wrong,k);
  put('power',`${q} ${c.text}. Answer A, B or C.`,c.letter,tab('Who uses geographic data',[['governments','plan services, set policy'],['businesses','choose sites, reach customers'],['individuals','plan routes, choose homes']],['For']),why||`The answer is ${right}.`,[right]);});
 for(const [q,v,why] of [['A fictional town has 3,600 children under age 5, and planners want one childcare place for every 4 children. How many places do they need?',900,'3,600 ÷ 4 = 900 places.'],
  ['In a fictional city, a GIS map shows that 2,400 of its 16,000 homes are too far from a park to walk. What percent of homes are not served?',15,'2,400 ÷ 16,000 × 100 = 15%.'],
  ['A fictional school has room for 600 students, and census projections show 750 school-age children in its zone in five years. How many more places will be needed?',150,'750 - 600 = 150 more places.'],
  ['A fictional survey of 800 households finds that 200 have no internet access. What percent lack access?',25,'200 ÷ 800 × 100 = 25%.'],
  ['Of 250 traffic crashes mapped in a fictional city, 90 happened at five intersections. What percent of the crashes happened there?',36,'90 ÷ 250 × 100 = 36%: a cluster worth fixing first.'],
  ['A fictional clinic needs to see 1,000 people in 25 working days. How many visits a day is that?',40,'1,000 ÷ 25 = 40 visits a day.']])
  put('power',q,v,tab('Planning with data',[['question','fictional numbers']],['']),why);
 /* concepts: distribution, density, concentration and pattern */
 for(const [p,a] of [[24000,300],[9000,450]])put('concepts',`A fictional county has ${n(p)} people living on ${a} square kilometers. What is its population density, in people per square kilometer?`,p/a,tab('A fictional county',[['people',n(p)],['area',`${a} km²`]]),`Density = people ÷ area = ${n(p)} ÷ ${a} = ${p/a} people per square kilometer.`);
 [['Shops packed tightly along one downtown street show what kind of concentration?','clustered',['dispersed','none at all'],'Shops packed close together on one street show a clustered, or agglomerated, concentration. Dispersed means spread far apart.'],
  ['Farmhouses spread far apart across the countryside show what kind of concentration?','dispersed',['clustered','linear'],'Farmhouses spread far apart show a dispersed concentration. Clustered would mean they were bunched close together.'],
  ['Towns strung out along a railroad line show what kind of pattern?','linear',['centralized','random'],'Towns lined up along a railroad form a linear pattern, following the line. Centralized means grouped around one center.'],
  ['What does density measure?','how many of something there are in a given area',['how spread out things are from each other','the shape that things make on a map'],'Density is the number of things in a given area, such as people per square kilometer. How spread out they are is concentration.'],
  ['Two towns have the same number of houses on the same area of land, but in one the houses are bunched together. Which is true?','their density is the same, but their concentration differs',['their density and concentration are both the same','their density differs, but their concentration is the same'],'Density counts how many in an area, so it is the same in both towns. Concentration is how spread out they are, so it differs.'],
  ['Neighborhoods arranged around one central market show what kind of pattern?','centralized',['linear','random'],'Neighborhoods grouped around one central market form a centralized pattern. Linear would follow a line, like a road or river.']].forEach(([q,right,wrong,why],k)=>{const c=choose(right,wrong,k+1);
  put('concepts',`${q} ${c.text}. Answer A, B or C.`,c.letter,tab('Distribution',[['density','how many in an area'],['concentration','clustered or dispersed'],['pattern','the shape: linear, centralized, random']],['Means']),why||`The answer is ${right}.`,[right]);});
 /* hei: determinism and possibilism, sustainability, resources and land use */
 [['What is environmental determinism?','the idea that the physical environment decides how societies develop',['the idea that people face no limits from nature','the study of map projections'],'Environmental determinism is the idea that climate and landforms decide how societies develop. Geographers today reject it.'],
  ['What is possibilism?','the idea that the environment sets limits, but people choose among many ways to live within them',['the idea that climate decides whether a culture succeeds','the idea that resources never run out'],'Possibilism says nature sets limits but people choose among many ways to live within them, using culture and technology.'],
  ['Why do most geographers today reject environmental determinism?','it ignores human choice and culture, and it was used to claim some peoples were superior',['experiments proved it wrong in a laboratory','it explains every culture perfectly'],'Determinism ignores human choice and culture, and it was used to claim that peoples in some climates were superior, which helped justify colonialism.'],
  ['Farmers cut terraces into steep hillsides to grow rice. Which idea does this best show?','possibilism',['environmental determinism','time-space compression'],'Terraces show people choosing a way to farm steep land the environment seemed to rule out. Nature set limits, and people found a way within them.'],
  ['Someone claims that people in hot climates cannot work hard. Which rejected idea is this?','environmental determinism',['possibilism','sustainability'],'Saying climate decides how hard people work is environmental determinism, which geographers reject. It ignores culture and choice.'],
  ['What does sustainability mean?','meeting today\'s needs without harming the ability of future generations to meet theirs',['using resources as fast as possible','never using any natural resources'],'Sustainability means meeting today\'s needs without harming future generations\' ability to meet theirs. It does not mean using no resources at all.'],
  ['Which of these is a renewable resource?','solar energy',['coal','natural gas'],'Sunlight keeps arriving, so solar energy is renewable. Coal and natural gas took millions of years to form and are nonrenewable.'],
  ['Which of these is a nonrenewable resource?','oil',['wind','sunlight'],'Oil forms over millions of years, so once used it is gone for human purposes. Wind and sunlight are renewable.'],
  ['Why is pumping groundwater faster than rain refills it a sustainability problem?','the supply runs down for future users',['groundwater refills instantly','pumping adds water to the aquifer'],'If pumping is faster than rain recharges the aquifer, the water table drops, leaving less for future users. That is not sustainable.'],
  ['People in the Netherlands built dikes and drained land to farm below sea level. What does this show?','people changing the environment to meet their needs',['the environment deciding everything people do','a perceptual region'],'Dikes and drained polders show people changing the environment to meet their needs. Nature did not decide what the Dutch could do.'],
  ['A desert community uses drip irrigation to grow crops with little water. Which idea fits best?','possibilism',['environmental determinism','distance decay'],'Drip irrigation shows people finding a way to farm within a dry climate\'s limits. That fits possibilism, not determinism.'],
  ['Clearing a forest for farms can cause soil erosion that later hurts the farms. What does this show?','human changes to the environment can come back to affect people',['people and the environment never affect each other','erosion is caused by map projections'],'Clearing forest is a human change to the land. The erosion it causes later hurts the farms, showing how human-environment effects loop back.'],
  ['What is land use?','how people use an area of land, such as for farms, homes or industry',['the size of a country','the slope of the land'],'Land use is how people use an area of land, such as for farms, homes, industry or parks. It is not the land\'s size or slope.'],
  ['Which farming practice is more sustainable?','rotating crops to keep the soil healthy',['planting the same crop until the soil is worn out','clearing new forest every year'],'Rotating crops helps keep soil nutrients and structure in balance, so the land stays productive for the future. Planting one crop until it is worn out is not sustainable.'],
  ['A dam makes electricity but floods a valley and blocks fish from swimming upstream. What does this show?','changes to the environment can bring both benefits and costs',['dams have no effect on rivers','the environment controls every human choice'],'A dam brings benefits, such as electricity, and costs, such as a flooded valley and blocked fish runs. Changes to the environment often have both.'],
  ['Why have so many cities grown up beside rivers and coasts?','water serves for drinking, farming and transport',['rivers keep the land cold','laws require cities to be on water'],'Rivers and coasts give water for drinking and farming, and routes for transport and trade, so many cities grew up beside them.']].forEach(([q,right,wrong,why],k)=>{const c=choose(right,wrong,k);
  put('hei',`${q} ${c.text}. Answer A, B or C.`,c.letter,tab('People and environment',[['determinism','nature decides (rejected)'],['possibilism','nature limits, people choose'],['sustainability','meet needs now and later']],['Idea']),why||`The answer is ${right}.`,[right]);});
 for(const [q,v,why] of [['A fictional aquifer holds 900 billion liters. People pump out 30 billion liters a year and rain refills 12 billion. If nothing changes, in how many years will it be empty?',50,'It loses 30 - 12 = 18 billion liters a year: 900 ÷ 18 = 50 years.'],
  ['A fictional lake holds 400 million liters. Towns take 25 million liters a year and rivers add 15 million. If nothing changes, in how many years will it be empty?',40,'It loses 25 - 15 = 10 million liters a year: 400 ÷ 10 = 40 years.'],
  ['A fictional country makes 60 units of electricity: 15 from wind, 9 from solar and the rest from coal. What percent comes from wind and solar?',40,'(15 + 9) ÷ 60 × 100 = 40%.'],
  ['A fictional forest has 5,000 hectares. Each year 200 hectares are cut and 150 are replanted. How many hectares of forest are lost each year?',50,'200 - 150 = 50 hectares a year.']])
  put('hei',q,v,tab('Resources',[['question','fictional numbers']],['']),why);
 /* scales: patterns at different scales of analysis */
 for(const [d,k] of [['data on traffic at one intersection','local'],['data comparing the countries of the Middle East','regional'],['data on rainfall across the planet','global'],['data comparing the regions of France','national']])
  put('scales',`A study uses ${d}. At which scale of analysis is it: local, regional, national, or global?`,k,tab('Scale of analysis',[['data',d]],['']),`It looks at ${k==='local'?'a small place':k==='regional'?'a group of countries':k==='national'?'the parts of one country':'the whole world'}: ${k} scale.`);
 [['A national map shows a country\'s population rising, but some of its towns are shrinking. What does this show?','a pattern at one scale can hide differences at another',['the map must be wrong','towns are left out of national data'],'A national total can grow while some towns shrink. A pattern seen at one scale can hide different patterns at a smaller scale.'],
  ['Which scale of analysis would best show which neighborhoods in a city lack grocery stores?','local',['global','national'],'Comparing neighborhoods within one city needs the local scale. A national or global view would blur those differences.'],
  ['Which scale of analysis would best compare carbon emissions among all the world\'s countries?','global',['local','national'],'Comparing all the world\'s countries is a study at the global scale. Local and national scales look at much smaller areas.'],
  ['Why might a geographer study one problem at several scales?','different causes and patterns show up at different scales',['data exist at only one scale','results never change with scale'],'Causes and patterns can differ by scale. Studying a problem locally, nationally and globally gives a fuller picture.'],
  ['A country\'s average income is high, but one of its regions is very poor. What does this show?','a national average can hide regional differences',['the poor region must be in another country','an average shows every difference'],'An average combines rich and poor areas into one number. A high national average can hide a poor region within the country.'],
  ['At which scale of analysis is a study of the countries of the European Union?','regional',['local','global'],'A group of countries, like the European Union, is studied at the regional scale. Global would mean the whole world.'],
  ['What does "scale of analysis" mean?','the size of the area a study looks at, from local to global',['the ratio of map distance to ground distance','the number of maps in an atlas'],'Scale of analysis is the size of area a study looks at, from local to global. The ratio of map distance to ground distance is map scale.'],
  ['Voting results by county show patterns that state totals hide. Why?','smaller units show more detail',['counties vote on different days','state totals include other countries'],'County results are smaller units, so they show local differences that get averaged away in statewide totals.']].forEach(([q,right,wrong,why],k)=>{const c=choose(right,wrong,k+2);
  put('scales',`${q} ${c.text}. Answer A, B or C.`,c.letter,tab('Scales of analysis',[['local','a neighborhood, a town'],['regional','a group of countries or part of one'],['national','one country'],['global','the whole world']],['Looks at']),why||`The answer is ${right}.`,[right]);});
 /* regions: overlap, nodes and contested edges */
 [['Can one place belong to more than one region at the same time?','yes: regions can overlap, like a city in both a state and a time zone',['no: every place is in exactly one region','only if it sits on a border'],'Regions are defined by different traits, so they can overlap. A city can sit in a state, a time zone and a sports fan region at once.'],
  ['Why do people disagree about where the Midwest ends?','it is a perceptual region, and people picture its edges differently',['its borders are set by law','it is defined by one government'],'The Midwest is a perceptual region: people define it by their own ideas and feelings, so they picture its edges differently.'],
  ['What is the central point of a functional region called?','the node',['the boundary','the periphery'],'A functional region is organized around a central point, called the node, such as a city, airport or TV station.'],
  ['As you move away from the node of a functional region, what usually happens to its ties?','they weaken',['they grow stronger','they stay exactly the same'],'Ties to the node, such as commuting or delivery, usually weaken with distance. This is called distance decay.'],
  ['Which data would define a formal region where most people speak French?','the main language spoken in each area',['where people imagine "French country" to be','the delivery area of one newspaper'],'A formal region shares one measurable trait. For a French-speaking region, that trait is the main language spoken in each area.'],
  ['Why are the boundaries of regions often argued over?','regions are human ways of grouping places, so people draw them differently',['every region has a fixed natural boundary','satellites measure region boundaries exactly'],'Regions are made by people to group places, and people use different traits and ideas, so they draw the edges differently.'],
  ['Which of these is a functional region?','the area served by one airport',['the Sahara Desert','"the Heartland"'],'An airport\'s service area is organized around one node, the airport, so it is a functional region. The Sahara is a formal region.'],
  ['Which of these is a perceptual region?','"the Rust Belt" as people picture it',['the area one cell tower covers','the member countries of the European Union'],'The Rust Belt is defined by how people picture it, not by fixed lines, so it is a perceptual region. A cell tower\'s area is functional.']].forEach(([q,right,wrong,why],k)=>{const c=choose(right,wrong,k);
  put('regions',`${q} ${c.text}. Answer A, B or C.`,c.letter,tab('Regions',[['formal','one shared trait'],['functional','around a node'],['perceptual','in people\'s minds']],['Meaning']),why||`The answer is ${right}.`,[right]);});
}};
